RoadSign("A18", "Horse riders", "signs/a18.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-ridande/"),
RoadSign("A19", "Animals", "signs/a19.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-djur/"),
RoadSign("A20", "Roadworks", "signs/a20.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagarbete/"),
