RoadSign("A27", "Soft verge or high carriageway edge", "signs/a27.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-svag-vagkant-eller-hog-korbanekant/"),
RoadSign("A28", "Junction", "signs/a28.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagkorsning/"),
RoadSign("A29", "Warning for a junction where road users on a connecting road are obliged to give way or stop", "signs/a29.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagkorsning-dar-trafikanter-pa-anslutande-vag-har-vajningsplikt-eller-stopplikt/"),
RoadSign("A30", "Roundabout ahead", "signs/a30.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-cirkulationsplats/"),
RoadSign("A31", "Slow-moving vehicles", "signs/a31.png", "https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-langsamtgaende-fordon/"),
